const form=document.getElementById("leaveForm"),printArea=document.getElementById("printArea"),printBtn=document.getElementById("printBtn"),printHint=document.getElementById("printHint");form&&form.addEventListener("submit",e=>{e.preventDefault();const n=new FormData(form),t=l=>(n.get(l)||"").trim(),a=t("company"),p=t("manager"),i=t("employee"),s=t("type"),r=t("start"),d=t("end"),o=t("days"),m=t("date");printArea.innerHTML=`
      <div style="text-align:right;margin-bottom:18px">
        <p style="margin:0">Генеральному директору ${esc(a)}</p>
        <p style="margin:0">${esc(p)}</p>
        <p style="margin:0">от ${esc(i)}</p>
      </div>
      <div style="text-align:center;font-size:19px;letter-spacing:1.5px;margin:26px 0 20px">ЗАЯВЛЕНИЕ</div>
      <p>Прошу предоставить мне ${esc(s)} с «${esc(r)}» по «${esc(d)}» продолжительностью ${esc(o)} календарных дней.</p>
      <div style="display:flex;justify-content:space-between;margin-top:48px;font-size:14px">
        <span>«${esc(m)}»</span><span>_______________ / ${esc(i)} /</span>
      </div>
    `,printBtn&&(printBtn.disabled=!1),printHint&&(printHint.hidden=!1),printBtn.focus()}),printBtn&&printBtn.addEventListener("click",()=>window.print());function esc(e){return e.replace(/[&<>"']/g,n=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"})[n])}
